import { subprocessEnvironment } from '../utils/subprocessEnvironment';
import { createLogger } from '../utils/logger';
import fs from 'fs';
import path from 'path';
import net from 'net';
import { exec } from 'child_process';
import { promisify } from 'util';
import {
  listStaticHtmlEntryFiles,
  resolveStaticProjectTarget,
} from './staticProjectTarget';
import { errorMessage } from '../utils/errorMessage';

const log = createLogger('ProjectDetectionService');
const execAsync = promisify(exec);

const MIN_VALID_TCP_PORT = 1;
const MAX_EXCLUSIVE_VALID_TCP_PORT = 65_536;
const RIVET_LOOPBACK_SCAN_PORT_MIN = 4000;
const RIVET_LOOPBACK_SCAN_PORT_MAX = 4010;
const DEV_SERVER_HTTP_PROBE_TIMEOUT_MS = 2000;
const DEFAULT_DEV_SERVER_HOST_LABEL = 'localhost';
const VITE_PACKAGE_NAME = 'vite';
const VITE_DEV_COMMAND_PATTERN = /(?:^|[\s;&|])(?:\S*[/\\])?vite(?:$|[\s;&|])/;

type Project = {
  id: string;
  path: string;
  devServerPort: number;
  devServerHost?: string;
  status: 'detected' | 'connected' | 'error';
  packageManager: 'npm' | 'yarn' | 'pnpm';
  framework: Framework;
  entryPoint?: string;
};

export type Framework =
  'nextjs' | 'vite' | 'cra' | 'remix' | 'svelte' | 'static';

type FrameworkConfig = {
  name: Framework;
  packageJsonIndicators: string[];
  configFiles: string[];
  devCommand: string;
  defaultPort: number;
};

type IpFamily = 4 | 6;

const FRAMEWORK_CONFIGS: FrameworkConfig[] = [
  {
    name: 'nextjs',
    packageJsonIndicators: ['next'],
    configFiles: ['next.config.js', 'next.config.ts', 'next.config.mjs'],
    devCommand: 'dev',
    defaultPort: 3000,
  },
  {
    name: 'vite',
    packageJsonIndicators: ['vite'],
    configFiles: ['vite.config.js', 'vite.config.ts'],
    devCommand: 'dev',
    defaultPort: 5173,
  },
  {
    name: 'cra',
    packageJsonIndicators: ['react-scripts'],
    configFiles: [],
    devCommand: 'start',
    defaultPort: 3000,
  },
  {
    name: 'remix',
    packageJsonIndicators: ['@remix-run/'],
    configFiles: ['remix.config.js'],
    devCommand: 'dev',
    defaultPort: 3000,
  },
  {
    name: 'svelte',
    packageJsonIndicators: ['@sveltejs/kit', 'svelte'],
    configFiles: ['svelte.config.js'],
    devCommand: 'dev',
    defaultPort: 5173,
  },
];

const hasPackageDependency = (
  dependencies: Record<string, unknown>,
  packageName: string,
): boolean => Object.prototype.hasOwnProperty.call(dependencies, packageName);

const scriptInvokesVite = (script: unknown): boolean =>
  typeof script === 'string' && VITE_DEV_COMMAND_PATTERN.test(script);

export class ProjectDetectionService {
  detectFramework(projectPath: string): Framework {
    const packageJsonPath = path.join(projectPath, 'package.json');

    log.debug(`Looking for package.json at: ${packageJsonPath}`);
    log.debug(`Project path: ${projectPath}`);

    if (!fs.existsSync(packageJsonPath)) {
      if (listStaticHtmlEntryFiles(projectPath).length > 0) {
        log.info('Detected static project (HTML present, no package.json)');
        return 'static';
      }
      if (fs.existsSync(path.join(projectPath, '.rivet'))) {
        log.info(
          'Detected Rivet history workspace (.rivet present, no package.json / index.html)',
        );
        return 'static';
      }
      if (!fs.existsSync(projectPath)) {
        throw new Error(`Project path does not exist: ${projectPath}`);
      }
      log.info(
        'Empty workspace (no package.json / index.html / .rivet) — treating as a blank static start point',
      );
      return 'static';
    }

    const packageJson = JSON.parse(fs.readFileSync(packageJsonPath, 'utf8'));
    const dependencies = {
      ...packageJson.dependencies,
      ...packageJson.devDependencies,
    };
    const viteScriptIndicator = scriptInvokesVite(packageJson.scripts?.dev);
    const viteDependencyIndicator = hasPackageDependency(
      dependencies,
      VITE_PACKAGE_NAME,
    );

    for (const config of FRAMEWORK_CONFIGS) {
      const hasPackageIndicator = config.packageJsonIndicators.some(
        (indicator) =>
          Object.keys(dependencies).some((dep) => dep.includes(indicator)),
      );
      const hasScriptIndicator = config.name === 'vite' && viteScriptIndicator;
      const hasIndicator = hasPackageIndicator || hasScriptIndicator;
      const canDetectWithoutConfig =
        config.name === 'vite' &&
        (viteDependencyIndicator || hasScriptIndicator);

      if (hasIndicator) {
        const hasConfigFile =
          config.configFiles.length === 0 ||
          config.configFiles.some((configFile) =>
            fs.existsSync(path.join(projectPath, configFile)),
          );

        if (hasConfigFile || canDetectWithoutConfig) {
          log.info(`Detected ${config.name} framework`);
          return config.name;
        }
      }
    }

    log.debug('Unknown framework, defaulting to Next.js');
    return 'nextjs';
  }

  async detectPackageManager(
    projectPath: string,
  ): Promise<'npm' | 'yarn' | 'pnpm'> {
    if (fs.existsSync(path.join(projectPath, 'yarn.lock'))) {
      return 'yarn';
    }
    if (fs.existsSync(path.join(projectPath, 'pnpm-lock.yaml'))) {
      return 'pnpm';
    }
    if (fs.existsSync(path.join(projectPath, 'package-lock.json'))) {
      return 'npm';
    }

    return 'npm';
  }

  readConfiguredPort(projectPath: string): number | undefined {
    const viteConfigFiles = [
      'vite.config.ts',
      'vite.config.js',
      'vite.config.mjs',
    ];
    for (const configFile of viteConfigFiles) {
      const configPath = path.join(projectPath, configFile);
      if (fs.existsSync(configPath)) {
        try {
          const content = fs.readFileSync(configPath, 'utf8');
          const match = content.match(
            /server\s*:\s*\{((?:[^{}]|\{[^{}]*\})*)port\s*:\s*(\d+)/s,
          );
          if (match) {
            const port = parseInt(match[2], 10);
            log.debug(`Found configured port ${port} in ${configFile}`);
            return port;
          }
        } catch {}
      }
    }
    return undefined;
  }

  async findRunningDevServer(
    projectPath: string,
    preferredPort?: number,
  ): Promise<{ port: number; host: string } | null> {
    const normalizedProjectPath = this.normalizeFilesystemPath(projectPath);
    const fallbackPorts = [
      3000, 5173, 3001, 3002, 5174, 6006, 6007, 8080, 4200, 8000,
    ];

    const configuredPort = this.readConfiguredPort(projectPath);
    let commonPorts = configuredPort
      ? [configuredPort, ...fallbackPorts.filter((p) => p !== configuredPort)]
      : [...fallbackPorts];

    const isUsablePreferredPort =
      typeof preferredPort === 'number' &&
      preferredPort >= MIN_VALID_TCP_PORT &&
      preferredPort < MAX_EXCLUSIVE_VALID_TCP_PORT;

    if (isUsablePreferredPort) {
      commonPorts = [
        preferredPort,
        ...commonPorts.filter((p) => p !== preferredPort),
      ];
    }

    const hosts: Array<{ urlHost: string; ipFamily: IpFamily }> = [
      { urlHost: '127.0.0.1', ipFamily: 4 },
      { urlHost: '[::1]', ipFamily: 6 },
    ];

    for (const port of commonPorts) {
      if (
        port >= RIVET_LOOPBACK_SCAN_PORT_MIN &&
        port <= RIVET_LOOPBACK_SCAN_PORT_MAX
      ) {
        continue;
      }
      for (const host of hosts) {
        try {
          const response = await fetch(`http://${host.urlHost}:${port}`, {
            method: 'GET',
            signal: AbortSignal.timeout(DEV_SERVER_HTTP_PROBE_TIMEOUT_MS),
          });

          if (response.ok) {
            const isOwnedBySelectedProject = await this.isPortOwnedByProject({
              normalizedProjectPath,
              port,
              ipFamily: host.ipFamily,
            });
            if (!isOwnedBySelectedProject) {
              log.debug(
                `Skipping ${host.urlHost}:${port} because listener process path does not match selected project`,
              );
              continue;
            }

            log.info(
              `Found running dev server on port ${port} (via ${host.urlHost}). Status: ${response.status}`,
            );
            return { port, host: 'localhost' };
          } else {
            log.debug(
              `Checked http://${host.urlHost}:${port}, but returned status ${response.status}`,
            );
          }
        } catch (error) {
          log.trace(
            `Could not reach http://${host.urlHost}:${port}: ${errorMessage(error)}`,
          );
          continue;
        }
      }
    }

    log.debug('No running dev server found');
    return null;
  }

  async detectProject(
    projectPath: string,
    overrideFramework?: Framework,
    entryPath?: string,
    preferredDevServerPort?: number,
  ): Promise<Project> {
    log.info(`Detecting project in: ${projectPath}`);

    const packageManager = await this.detectPackageManager(projectPath);
    const framework = overrideFramework || this.detectFramework(projectPath);

    let devServerPort = 0;
    let devServerHost = DEFAULT_DEV_SERVER_HOST_LABEL;
    if (framework !== 'static') {
      const runningServer = await this.findRunningDevServer(
        projectPath,
        preferredDevServerPort,
      );

      if (!runningServer) {
        throw new Error(
          'No running dev server found. Please start your dev server first (e.g., npm run dev)',
        );
      }

      devServerPort = runningServer.port;
      devServerHost = runningServer.host;
    }

    let entryPoint: string | undefined;
    if (framework === 'static') {
      const staticTarget = resolveStaticProjectTarget({
        targetPath: projectPath,
        entryPath,
      });
      entryPoint = staticTarget.entryPath;
      const fullEntryPath = path.join(projectPath, entryPoint);
      const isBlankStaticWorkspace =
        !entryPath &&
        staticTarget.htmlEntryFiles.length === 0 &&
        !fs.existsSync(fullEntryPath);

      if (!fs.existsSync(fullEntryPath) && !isBlankStaticWorkspace) {
        throw new Error(
          `Entry point not found: ${entryPoint}. Please ensure the file exists or specify a different --entry path.`,
        );
      }

      if (isBlankStaticWorkspace) {
        entryPoint = undefined;
        log.info('Detected blank static project without an entry point');
      } else {
        log.info(`Using entry point: ${entryPoint}`);
      }
    }

    const project: Project = {
      id: path.basename(projectPath),
      framework,
      path: projectPath,
      devServerPort,
      devServerHost,
      status: 'detected',
      packageManager,
      entryPoint,
    };

    log.info(`Detected project:`, project);
    return project;
  }

  isPortActive(port: number): Promise<boolean> {
    return new Promise((resolve) => {
      const socket = net.connect(port, 'localhost');
      socket.on('connect', () => {
        socket.destroy();
        resolve(true);
      });
      socket.on('error', () => {
        socket.destroy();
        resolve(false);
      });
      socket.setTimeout(500);
      socket.on('timeout', () => {
        socket.destroy();
        resolve(false);
      });
    });
  }

  private normalizeFilesystemPath(inputPath: string): string {
    const resolvedPath = path.resolve(inputPath);
    try {
      return fs.realpathSync(resolvedPath);
    } catch {
      return resolvedPath;
    }
  }

  private async isPortOwnedByProject(options: {
    normalizedProjectPath: string;
    port: number;
    ipFamily: IpFamily;
  }): Promise<boolean> {
    const { normalizedProjectPath, port, ipFamily } = options;
    const listenerPids = await this.getListeningPortPids({ port, ipFamily });
    if (listenerPids.length === 0) {
      return false;
    }
    for (const pid of listenerPids) {
      const processCwd = await this.getProcessCwd(pid);
      if (!processCwd) {
        continue;
      }
      const normalizedProcessPath = this.normalizeFilesystemPath(processCwd);
      if (normalizedProcessPath === normalizedProjectPath) {
        return true;
      }
    }
    return false;
  }

  private async getListeningPortPids(options: {
    port: number;
    ipFamily: IpFamily;
  }): Promise<number[]> {
    const { port, ipFamily } = options;
    try {
      const { stdout } = await execAsync(
        `lsof -nP -i${ipFamily}TCP:${port} -sTCP:LISTEN -Fp`,
        { env: subprocessEnvironment('verifier') },
      );
      const pids = stdout
        .split('\n')
        .map((line) => line.trim())
        .filter((line) => line.startsWith('p'))
        .map((line) => parseInt(line.slice(1), 10))
        .filter((pid) => Number.isInteger(pid) && pid > 0);
      return [...new Set(pids)];
    } catch {
      return [];
    }
  }

  private async getProcessCwd(pid: number): Promise<string | null> {
    if (!Number.isInteger(pid) || pid <= 0) {
      return null;
    }
    try {
      const { stdout } = await execAsync(`lsof -a -p ${pid} -d cwd -Fn`, {
        env: subprocessEnvironment('verifier'),
      });
      const cwdLine = stdout
        .split('\n')
        .map((line) => line.trim())
        .find((line) => line.startsWith('n'));
      if (!cwdLine) {
        return null;
      }
      return cwdLine.slice(1) || null;
    } catch {
      return null;
    }
  }
}
